package org.sleepwell.app;

import java.time.*;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MissedNightTest {
    private MissedNight.Event event(long at,MissedNight.Kind kind){return new MissedNight.Event(at,kind);}
    @Test public void actualPairsDoNotBridgeInteractiveBreaks(){List<MissedNight.Interval> pairs=MissedNight.pairs(List.of(event(20,MissedNight.Kind.OFF),event(30,MissedNight.Kind.ON),event(40,MissedNight.Kind.OFF),event(70,MissedNight.Kind.ON)),10,100);assertEquals(2,pairs.size());assertEquals(20,pairs.get(0).start);assertEquals(30,pairs.get(0).end);assertEquals(40,pairs.get(1).start);assertEquals(70,pairs.get(1).end);}
    @Test public void missingEndpointsAreNeverInferredAtWindowBounds(){assertTrue(MissedNight.pairs(List.of(event(20,MissedNight.Kind.ON),event(30,MissedNight.Kind.OFF)),10,100).isEmpty());assertTrue(MissedNight.pairs(List.of(event(5,MissedNight.Kind.OFF),event(20,MissedNight.Kind.ON),event(40,MissedNight.Kind.OFF),event(100,MissedNight.Kind.ON)),10,100).isEmpty());}
    @Test public void rebootAndShutdownInvalidatePendingScreenOff(){List<MissedNight.Interval> pairs=MissedNight.pairs(List.of(event(20,MissedNight.Kind.OFF),event(30,MissedNight.Kind.RESET),event(40,MissedNight.Kind.ON),event(50,MissedNight.Kind.OFF),event(60,MissedNight.Kind.ON)),10,100);assertEquals(1,pairs.size());assertEquals(50,pairs.get(0).start);}
    @Test public void duplicateOffUsesLatestEvidenceAndOnCannotCreateTwoPairs(){List<MissedNight.Interval> pairs=MissedNight.pairs(List.of(event(20,MissedNight.Kind.OFF),event(25,MissedNight.Kind.OFF),event(40,MissedNight.Kind.ON),event(50,MissedNight.Kind.ON)),10,100);assertEquals(1,pairs.size());assertEquals(25,pairs.get(0).start);assertEquals(40,pairs.get(0).end);}
    @Test public void zeroLengthPairIsDiscardedAndRegressingEvidenceFailsClosed(){assertTrue(MissedNight.pairs(List.of(event(20,MissedNight.Kind.OFF),event(20,MissedNight.Kind.ON)),10,100).isEmpty());assertThrows(IllegalArgumentException.class,()->MissedNight.pairs(List.of(event(40,MissedNight.Kind.OFF),event(30,MissedNight.Kind.ON)),10,100));}
    @Test public void longestUncoveredPairIsSuggestedWithoutTrimmingAroundRecords(){MissedNight.Interval first=new MissedNight.Interval(20,40),longest=new MissedNight.Interval(50,90);List<MissedNight.Interval> result=MissedNight.available(List.of(first,longest),List.of(new MissedNight.Interval(60,70)));assertEquals(1,result.size());assertTrue(first.same(result.get(0)));result=MissedNight.available(List.of(first,longest),List.of());assertTrue(longest.same(result.get(0)));}
    @Test public void adjacentRecordsAreAllowedButOpenRecordsBlockFutureEstimates(){assertFalse(MissedNight.overlaps(20,40,List.of(new MissedNight.Interval(10,20),new MissedNight.Interval(40,50))));assertTrue(MissedNight.overlaps(20,40,List.of(new MissedNight.Interval(30,Long.MAX_VALUE))));}
    @Test public void reviewedBoundsMayDifferFromPhoneIdleButStayInsideTheNight(){MissedNight.validateReview(15,80,10,100,100);assertThrows(IllegalArgumentException.class,()->MissedNight.validateReview(5,80,10,100,100));assertThrows(IllegalArgumentException.class,()->MissedNight.validateReview(15,101,10,100,100));assertThrows(IllegalArgumentException.class,()->MissedNight.validateReview(80,15,10,100,100));assertThrows(IllegalArgumentException.class,()->MissedNight.validateReview(15,80,10,100,70));}
    @Test public void nightWindowUsesActualDstInstantsInsteadOfFixedTwentyFourHours(){ZoneId zone=ZoneId.of("Europe/London");long now=Instant.parse("2026-10-25T15:00:00Z").toEpochMilli();MissedNight.Window window=new MissedNight.Window(LocalDate.of(2026,10,25),zone,now);assertEquals(25*3600000L,window.end-window.start);assertEquals(Instant.parse("2026-10-24T11:00:00Z").toEpochMilli(),window.start);}
    @Test public void morningWindowEndsAtQueryTimeAndOldOrFutureDatesAreRejected(){long now=Instant.parse("2026-10-23T07:00:00Z").toEpochMilli();MissedNight.Window window=new MissedNight.Window(LocalDate.of(2026,10,23),ZoneOffset.UTC,now);assertEquals(now,window.end);assertThrows(IllegalArgumentException.class,()->new MissedNight.Window(LocalDate.of(2026,10,24),ZoneOffset.UTC,now));assertThrows(IllegalArgumentException.class,()->new MissedNight.Window(LocalDate.of(2026,10,20),ZoneOffset.UTC,now));}
}
